result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/ab_funnel.py", "content": """"Three-variant funnel experiment analyzer.

Assigns users to arms (control/v1/v2) in a 2:1:1 ratio, simulates
purchase conversion, runs pairwise two-proportion z-tests
(control vs v1, control vs v2), and applies a Bonferroni correction
at alpha = 0.05.

Only the Python standard library is used (the z-test is implemented
by hand with `math`).
"""

from __future__ import annotations

import math
import random
from dataclasses import dataclass

ARMS = ("control", "v1", "v2")
TRUE_CONVERSION = {"control": 0.100, "v1": 0.102, "v2": 0.118}
RATIO = (2, 1, 1)
ALPHA = 0.05
N_USERS = 30_000


@dataclass(frozen=True)
class ArmStats:
    arm: str
    assigned: int
    converted: int

    @property
    def rate(self) -> float:
        return self.converted / self.assigned if self.assigned else float("nan")


def build_assignments(seed: int = 77, n_users: int = N_USERS):
    """Simulate assignment + conversion outcomes.

    Returns dict[arm] -> ArmStats.
    """
    rng = random.Random(seed)
    total_ratio = sum(RATIO)
    cutpoints = []
    acc = 0
    for r in RATIO:
        acc += r
        cutpoints.append(acc / total_ratio)

    stats = {arm: {"assigned": 0, "converted": 0} for arm in ARMS}
    for _ in range(n_users):
        u = rng.random()
        arm = ARMS[-1]
        for i, cp in enumerate(cutpoints):
            if u < cp:
                arm = ARMS[i]
                break
        stats[arm]["assigned"] += 1
        if rng.random() < TRUE_CONVERSION[arm]:
            stats[arm]["converted"] += 1

    return {
        arm: ArmStats(arm, s["assigned"], s["converted"]) for arm, s in stats.items()
    }


def two_proportion_z_test(
    x1: int, n1: int, x2: int, n2: int
) -> tuple[float, float]:
    """Pooled two-proportion z-test.

    Returns (z_statistic, two_sided_p_value).
    """
    if n1 <= 0 or n2 <= 0:
        raise ValueError("both groups must have positive sample sizes")
    p1, p2 = x1 / n1, x2 / n2
    pool = (x1 + x2) / (n1 + n2)
    se = math.sqrt(pool * (1.0 - pool) * (1.0 / n1 + 1.0 / n2))
    if se == 0.0:
        return 0.0, 1.0
    z = (p1 - p2) / se
    # Two-sided p-value: P(Z > |z|) * 2 == erfc(|z| / sqrt(2))
    p_value = math.erfc(abs(z) / math.sqrt(2.0))
    return z, p_value


def bonferroni_threshold(alpha: float, n_comparisons: int) -> float:
    """Per-comparison significance threshold under Bonferroni correction."""
    if n_comparisons <= 0:
        raise ValueError("n_comparisons must be positive")
    return alpha / n_comparisons


def analyze(seed: int = 77, n_users: int = N_USERS, alpha: float = ALPHA) -> dict:
    """Run the funnel analysis end-to-end.

    Returns a dict:
      {
        "assignments": {arm: {"assigned": int, "converted": int, "rate": float}},
        "comparisons": {
            name: {
              "z": float,
              "raw_p": float,
              "significant_raw": bool,
              "significant_corrected": bool,
            }, ...
        },
        "bonferroni_alpha": float,
        "verdict": str,
      }
    """
    stats = build_assignments(seed=seed, n_users=n_users)

    pairs = [("control_vs_v1", "v1"), ("control_vs_v2", "v2")]
    m = len(pairs)
    corrected_alpha = bonferroni_threshold(alpha, m)

    comparisons = {}
    for name, variant in pairs:
        c = stats["control"]
        v = stats[variant]
        z, p = two_proportion_z_test(c.converted, c.assigned, v.converted, v.assigned)
        comparisons[name] = {
            "z": z,
            "raw_p": p,
            "significant_raw": p < alpha,
            "significant_corrected": p < corrected_alpha,
        }

    winners = [n for n, r in comparisons.items() if r["significant_corrected"]]
    if winners:
        verdict = (
            f"After Bonferroni correction (per-comparison alpha={corrected_alpha:.4f}), "
            f"significant uplift detected in: {', '.join(winners)}. "
            "Roll out the winning variant(s)."
        )
    else:
        verdict = (
            f"After Bonferroni correction (per-comparison alpha={corrected_alpha:.4f}), "
            "no variant shows a statistically significant difference from control."
        )

    return {
        "assignments": {
            arm: {
                "assigned": s.assigned,
                "converted": s.converted,
                "rate": s.rate,
            }
            for arm, s in stats.items()
        },
        "comparisons": comparisons,
        "bonferroni_alpha": corrected_alpha,
        "verdict": verdict,
    }


if __name__ == "__main__":
    import json

    result = analyze()
    print(json.dumps(result, indent=2))
"})
